mcqs.question:
What will be logged?

```javascript
function foo() {
  console.log(a);
  var a = 5;
}
foo();
```

What is the output of the following code?

```js
function test() {
  var a = 1;
  if (true) {
    var a = 2;
    console.log(a);
  }
  console.log(a);
}
test();
```

What will the following code output?

```js
const add = (x) => (y) => x + y;
console.log(add(2)(3));
```

What is the output of this code?

```js
console.log(x);
var x = 10;
```

What will the following function return?

```js
function f() {
  return
  {
    key: 'value'
  };
}
console.log(f());
```

What will this output?

```js
const obj = {
  x: 10,
  getX() {
    return this.x;
  }
};
const getX = obj.getX;
console.log(getX());
```

What will this code output?

```js
var x = 1;
function outer() {
  var x = 2;
  function inner() {
    console.log(x);
  }
  inner();
}
outer();
```

What will the following output?

```js
(function(){
  let x = y = 5;
})();
console.log(typeof x);
console.log(typeof y);
```

What is the output of this code?

```js
let f = function() {
  return this;
};
console.log(f());
```

What will this code log?

```js
function sayHi() {
  console.log(this.name);
}
const person = { name: 'Alice', sayHi };
person.sayHi();
```

What is the result of this code?

```js
const func = () => {
  return arguments;
};
func(1, 2, 3);
```

What will the following code output?

```js
function outer() {
  let count = 0;
  return function() {
    count++;
    return count;
  };
}
const counter = outer();
console.log(counter());
console.log(counter());
```

What will this code output?

```js
(function(x){
  return (function(y){
    console.log(x);
  })(2);
})(1);
```

What is the output?

```js
function foo() {
  console.log(this);
}
foo.call({a:1});
```

